 private void InvalidateConnection(){accountInfo.Text="Not connected";dryStamp="";api?.Dispose();api=null;client=null;store=null;drafts=[];upload.ItemsSource=null;download.ItemsSource=null;downloadRows=[];comparison.ItemsSource=null;detail.Clear();preview=null;previewReason="Connection changed; prepare and preview again.";status.Text="Connection changed. Pull or Prepare will validate the new connection.";}
 private void InvalidatePlan(){dryStamp="";preview=null;previewReason="Upload options changed; prepare the selection again.";drafts=[];upload.ItemsSource=null;status.Text=previewReason;}
 private void Add(Panel panel,string title,Action action){var button=Button(title);panel.Children.Add(button);button.Click+=(_,_)=>{try{action();}catch(Exception ex){status.Text=SyncJson.Safe(ex.Message);}};}
 private Button Button(string title){var b=new Button{Content=title,Foreground=Brushes.Black,Padding=new(8,5,8,5),Margin=new(0,4,7,4)};buttons.Add(b);return b;}
 private void AddAsync(Panel panel,string title,Func<Task> action){var b=Button(title);panel.Children.Add(b);b.Click+=async(_,_)=>await Run(action);}
 private async Task Run(Func<Task> action){if(!await operation.WaitAsync(0)){status.Text="Another website-sync operation is running; wait for it to finish.";return;}foreach(var b in buttons)b.IsEnabled=false;endpoint.IsEnabled=token.IsEnabled=upload.IsEnabled=download.IsEnabled=scope.IsEnabled=notes.IsEnabled=radios.IsEnabled=false;try{await action();}catch(Exception ex){accountInfo.Text="Connection not verified for this operation";status.Text=SyncJson.Safe(ex.Message);}finally{RefreshAccess();endpoint.IsEnabled=token.IsEnabled=upload.IsEnabled=download.IsEnabled=scope.IsEnabled=notes.IsEnabled=radios.IsEnabled=true;operation.Release();}}
 private void RefreshAccess(){foreach(var b in buttons)b.IsEnabled=b.Content?.ToString() is not("Preview selected on server (dry run)" or "Upload previewed selection…")||client?.Scope!="read";}
 private void SaveConnection(){using(var test=apiFactory(endpoint.Text.Trim(),token.Password)){}Directory.CreateDirectory(root);WebsiteCredentials.Save(Path.Combine(root,"token.bin"),token.Password);SyncJson.Atomic(Path.Combine(root,"connection.json"),new JsonObject{["endpoint"]=endpoint.Text.Trim()}.ToJsonString());status.Text="Connection saved; token protected for this Windows user. No network request made.";}
 private void InitializeConnection(){if(client!=null)return;api=apiFactory(endpoint.Text.Trim(),token.Password);store=new(Path.Combine(root,"accounts"));client=new(api,store);}
 private void AccountBadge(){accountInfo.Text=$"Account {client!.UserLabel} · {(client.Scope=="write"?"Read and write":"Read only")} · {api!.Endpoint.Host}";}
 private async Task Connect(){InitializeConnection();await client!.Test(cancel.Token);AccountBadge();RefreshDownloads();status.Text=$"Connected · {store!.Data.Remote.Count} cached records · {store.Data.Pending.Count} awaiting review. No upload made.";}
 private void RequireConnection(){if(client==null||store==null||client.Account.Length==0||client.Scope is not("read" or "write"))throw new IOException("Pull changes to load the saved account and review queue.");}
 private async Task Pull(){InitializeConnection();await client!.Pull(cancel.Token);AccountBadge();dryStamp="";preview=null;previewReason="Website changes were refreshed; preview the selection again.";RefreshDownloads();status.Text=$"Changes saved through cursor {store!.Data.Cursor}; {store.Data.Pending.Count} awaiting review. Nothing applied to the local library.";}
 private async Task PrepareUpload(){InitializeConnection();await client!.Test(cancel.Token);if(!store!.Data.InitialScanComplete)await client.Pull(cancel.Token);AccountBadge();RefreshDownloads();var bundle=frequencies.WebsiteBundle(scope.SelectedIndex==0,notes.IsChecked==true);drafts=SyncMapping.Build(bundle,store.Data,notes.IsChecked==true,radios.IsChecked==true);upload.ItemsSource=drafts.Select(d=>new UploadRow(d)).ToArray();upload.SelectAll();dryStamp="";preview=null;previewReason="Prepared selection needs a dry preview.";status.Text=$"Prepared {drafts.Count} records including dependencies. Select rows; required parents are included automatically. Preview splits requests at 200 records and the size limit.";}
 private List<SyncDraft> SelectedUploads()=>SyncUploadPlan.Select(upload.SelectedItems.OfType<UploadRow>().Select(r=>r.Draft),drafts,store!.Data);
 private string Stamp(List<SyncDraft> selected)=>SyncUploadPlan.Stamp(selected,store!.Data);
 private async Task DryRun(){dryStamp="";preview=null;previewReason="Dry preview did not complete. Review the error and run preview again.";InitializeConnection();await client!.Test(cancel.Token);AccountBadge();var selected=SelectedUploads();var batches=SyncUploadPlan.Batches(selected,client);dryStamp="";preview=null;previewReason="Dry preview did not complete.";var combined=new JsonArray();bool ready=true;
  foreach(var batch in batches){var results=await client.Push(batch,true,cancel.Token);for(int i=0;i<results.Count;i++){string result=SyncJson.Text(results[i]?["status"]);if(result is not("created" or "updated" or "unchanged")&&!ExpectedDependencyError(results[i] as JsonObject,batch[i],selected,store!.Data))ready=false;combined.Add(results[i]?.DeepClone());}}
  dryStamp=ready?Stamp(selected):"";preview=ready?selected:null;previewReason=ready?"":"Dry preview has errors, conflicts or deleted records. Review the server results below.";detailTabs.SelectedIndex=1;detail.Text=SyncJson.Safe(combined.ToJsonString(new(){WriteIndented=true}));status.Text=ready?$"Dry preview ready: {selected.Count} records in {batches.Count} batches. New dependency reference errors are expected until parents are saved. Upload requires confirmation.":previewReason;
 }
 internal static bool ExpectedDependencyError(JsonObject? result,SyncDraft draft,IReadOnlyList<SyncDraft> selected,SyncDocument state){if(SyncJson.Text(result?["status"])!="error"||result?["errors"] is not JsonArray errors||errors.Count==0)return false;return errors.All(e=>new[]{"parent_ref","target_ref"}.Any(field=>{string reference=SyncJson.Text(draft.Record[field]);return reference.Length>0&&!state.Bindings.ContainsKey(reference)&&selected.Any(d=>d.Ref==reference)&&SyncJson.Text(e).StartsWith(field+" \""+reference+"\" was not found.",StringComparison.Ordinal);}));}
 private bool UploadReady(){var selected=SelectedUploads();if(preview==null||dryStamp.Length==0)throw new IOException(previewReason+" Run the dry preview after preparing and selecting records.");if(dryStamp!=Stamp(selected))throw new IOException("Selection, account or revisions changed since preview. Preview this selection again.");return true;}
 private async Task Upload(){InitializeConnection();await client!.Test(cancel.Token);AccountBadge();if(client.Scope!="write")throw new IOException("This token is read-only; no upload is available.");UploadReady();var selected=preview!;var batches=SyncUploadPlan.Batches(selected,client);if(MessageBox.Show(this,$"Upload {selected.Count} previewed records in {batches.Count} batches to {api!.Endpoint.Host}, account {client.UserLabel}? New records will be private. Existing visibility is retained; the website may fill profile ZIP/grid defaults. This writes to your website account.","Confirm selected website upload",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;
  await SendPreviewed(selected,batches);
 }
 private async Task SendPreviewed(List<SyncDraft> selected,List<List<SyncDraft>> batches)
 {
  dryStamp="";preview=null;previewReason="Previous upload was attempted. Pull/review results and prepare a fresh preview before another upload.";
  var expected=selected.ToDictionary(d=>d.Ref,d=>(Id:store!.Data.Bindings.GetValueOrDefault(d.Ref)?.Id??0,Rev:store!.Data.Bindings.GetValueOrDefault(d.Ref)?.Rev??0));var combined=new JsonArray();int completed=0;Exception? failure=null;
  try{for(int index=0;index<batches.Count;index++){status.Text=$"Uploading batch {index+1}/{batches.Count}; {completed}/{selected.Count} successful records saved.";var results=await client!.Push(batches[index],false,cancel.Token,expected);foreach(var result in results)combined.Add(result?.DeepClone());completed+=results.Count(r=>SyncJson.Text(r?["status"]) is "created" or "updated" or "unchanged");if(!SyncUploadPlan.Success(results))throw new IOException("A batch contains errors, conflicts or gone records; remaining batches were not sent.");}}
  catch(Exception ex){failure=ex;}
  detailTabs.SelectedIndex=1;detail.Text=SyncJson.Safe(combined.ToJsonString(new(){WriteIndented=true}));
  try{await client!.Pull(cancel.Token);RefreshDownloads();}catch(Exception ex){throw new IOException($"{completed}/{selected.Count} upload results saved. Echo pull/review could not finish: "+SyncJson.Safe(ex.Message)+(failure==null?"":". Upload also stopped: "+SyncJson.Safe(failure.Message)),ex);}
  if(failure!=null)throw new IOException($"Stopped with {completed}/{selected.Count} successful records saved. "+SyncJson.Safe(failure.Message)+" Pull/review results before preparing the remainder.",failure);
  status.Text=$"Uploaded {completed} records. Results and echoed changes saved; review the downloaded queue.";
 }

 private void RefreshDownloads(){if(store==null)return;var local=SyncMapping.Build(frequencies.WebsiteBundle(false,true),store.Data,true,true).Select(d=>d with{Record=SyncJson.Copy(client!.Prepare(d)["record"]!.AsObject())}).ToList();downloadRows=store.Data.Pending.OrderBy(p=>p.Key).Select(p=>new SyncReviewRow(p.Key,p.Value,store.Data,local)).ToList();FilterDownloads();}
 private void FilterDownloads(){string query=downloadFilter.Text.Trim();download.ItemsSource=downloadRows.Where(r=>query.Length==0||r.Search.Contains(query,StringComparison.OrdinalIgnoreCase)).ToArray();comparison.ItemsSource=null;}
 private void Review(bool overwrite,bool keepLocal)
 {
  RequireConnection();var ids=download.SelectedItems.OfType<SyncReviewRow>().Select(r=>r.Id).ToArray();if(ids.Length==0)throw new IOException("Select downloaded records first.");var plan=frequencies.PreviewWebsite(store!.Data,ids,overwrite,keepLocal,importNotes.IsChecked==true);var panel=new DockPanel{Margin=new(12)};var message=new TextBlock{Text=$"{plan.Applied.Count} can be applied; {plan.Held.Count} remain held. "+(overwrite?"Website values will replace the listed conflicting local fields.":keepLocal?"Link matching records while keeping local values.":"Conflicting local fields are held. Deletions retain local data unresolved."),Foreground=Brushes.Aquamarine,TextWrapping=TextWrapping.Wrap};DockPanel.SetDock(message,Dock.Top);panel.Children.Add(message);var apply=new Button{Content="Apply this reviewed plan",Foreground=Brushes.Black,IsEnabled=plan.Applied.Count>0};DockPanel.SetDock(apply,Dock.Bottom);panel.Children.Add(apply);var grid=Grid();grid.ItemsSource=plan.Library.Changes;panel.Children.Add(grid);var dialog=new Window{Owner=this,Title="Website download preview",Content=panel,Width=1000,Height=650,Background=Background,Foreground=Foreground};apply.Click+=(_,_)=>{try{frequencies.ApplyWebsite(plan,store);dialog.DialogResult=true;RefreshDownloads();dryStamp="";status.Text=$"Applied {plan.Applied.Count}; held {plan.Held.Count}. Local backup created.";}catch(Exception ex){message.Text=SyncJson.Safe(ex.Message);}};dialog.ShowDialog();
 }
 internal async Task RenderSmoke()
 {
  endpoint.Text="https://mrs-fixture.invalid/account/api.php";token.Password=WebsiteFixture.Secret;await Pull();RefreshAccess();if(client?.Scope!="read"||buttons.Where(b=>b.Content?.ToString()=="Upload previewed selection…").Any(b=>b.IsEnabled))throw new IOException("Read-only upload controls were not disabled.");await Pull();if(store?.Data.Pending.Count==0)throw new IOException("Fixture changes did not enter the review queue");scope.SelectedIndex=1;await PrepareUpload();download.SelectAll();if(Content is DockPanel body&&body.Children.OfType<TabControl>().FirstOrDefault() is {} tabs)tabs.SelectedIndex=1;download.SelectedIndex=0;UpdateLayout();var image=new RenderTargetBitmap((int)ActualWidth,(int)ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(this);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using var stream=File.Create(Path.Combine(AppContext.BaseDirectory,"ui-050-website-sync.png"));encoder.Save(stream);
 }
 internal async Task WriteWorkflowSmoke()
 {
  scope.SelectedIndex=1;await PrepareUpload();if(drafts.Count<=200)throw new IOException("Write smoke needs a multi-batch library");await DryRun();if(!UploadReady()||preview==null)throw new IOException("Successful preview did not unlock upload");int count=preview.Count;var prepared=preview;var batches=SyncUploadPlan.Batches(prepared,client!);if(batches.Count<2)throw new IOException("No batch split");
  upload.SelectedIndex=0;bool stale=false;try{UploadReady();}catch(IOException ex){stale=ex.Message.Contains("changed since preview");}if(!stale)throw new IOException("Changed selection retained upload approval");upload.SelectAll();if(!UploadReady())throw new IOException("Restoring exact selection lost preview");await Connect();if(!UploadReady())throw new IOException("Optional connection test invalidated unchanged preview");
  await SendPreviewed(prepared,batches);if(store!.Data.Bindings.Count!=count||store.Data.Pending.Count!=count)throw new IOException("Multi-batch write did not persist bindings and echoed review records");bool attempted=false;try{UploadReady();}catch(IOException){attempted=true;}if(!attempted)throw new IOException("A used preview was accepted again");notes.IsChecked=true;if(drafts.Count!=0||!status.Text.Contains("options changed"))throw new IOException("Plan invalidation did not explain why preparation is needed");
 }
 private sealed class UploadRow(SyncDraft draft){internal SyncDraft Draft=>draft;public string Type=>draft.Type;public string Label=>draft.Label;public string MHz=>SyncJson.Text(draft.Record["mhz"]);public string Reference=>draft.Ref;public string Warning=>draft.Warning;}

}

public sealed partial class FrequencyPanel
{
 internal DiscoveryBundle WebsiteBundle(bool selected,bool notes){if(selected&&selection.Count==0)throw new IOException("Select entries or a folder in Frequencies, or explicitly choose Entire library.");return RequireLibrary().ExportDiscoveries(selected?selection:null,SharingCatalog?.Invoke(),notes);}
 internal SyncImportPlan PreviewWebsite(SyncDocument state,IEnumerable<long> ids,bool overwrite=false,bool keep=false,bool notes=false)=>WebsiteImport.Preview(RequireLibrary(),state,ids,overwrite,notes,keep);
 internal void ApplyWebsite(SyncImportPlan plan,SyncStore store){if(plan.QueueStamp!=WebsiteImport.QueueStamp(store.Data))throw new IOException("The download queue changed; preview again.");RequireLibrary().ApplyReview(plan.Library);store.Data.Bindings=plan.Bindings;foreach(long id in plan.Applied)store.Data.Pending.Remove(id);foreach(var journal in store.Data.Journal.Where(j=>j.State=="conflict"&&store.Data.Bindings.TryGetValue(j.Ref,out var binding)&&plan.Applied.Contains(binding.Id)))journal.State="reviewed";store.Save();Rebuild();Notify("Reviewed website changes applied; local backup retained.");}
 internal Window WebsiteWindow(string root,Func<string,string,WebsiteApi>? factory=null)=>new WebsiteSyncWindow(this,root,factory){Owner=Window.GetWindow(this)};
}
